package thaumcraft.thaumaturgy;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import com.mojang.serialization.JsonOps;
import com.google.gson.JsonParser;
class FocusProgramTest {
    @Test void repeatedEffectsCostMoreAndCrystalsRemainExact(){var p=new FocusProgram("touch",List.of(new FocusProgram.Effect("fire",1,1),new FocusProgram.Effect("fire",1,1)));assertEquals(10,p.complexity());assertEquals(2,p.crystals().get("ignis"));assertEquals(1,p.crystals().get("aversio"));assertEquals(103,p.craftingVis(15));assertEquals(3,p.levels());}
    @Test void malformedNetworkProgramsAreRejected(){for(String json:List.of("{\"medium\":\"unknown\",\"effects\":[{\"kind\":\"fire\",\"power\":1,\"duration\":1}]}","{\"medium\":\"touch\",\"effects\":[]}","{\"medium\":\"touch\",\"effects\":[{\"kind\":\"op\",\"power\":1,\"duration\":1}]}","{\"medium\":\"touch\",\"effects\":[{\"kind\":\"fire\",\"power\":99,\"duration\":1}]}"))assertTrue(FocusProgram.CODEC.parse(JsonOps.INSTANCE,JsonParser.parseString(json)).error().isPresent());}
    @Test void persistenceKeepsExactOrderAndSettings(){var p=new FocusProgram("projectile",List.of(new FocusProgram.Effect("earth",3,1),new FocusProgram.Effect("frost",1,4)));var encoded=FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,p).getOrThrow();assertEquals(p,FocusProgram.CODEC.parse(JsonOps.INSTANCE,encoded).getOrThrow());assertEquals(19,p.complexity());}

    @Test void port14ProgramsDecodeWithoutMigration(){var json=JsonParser.parseString("{\"medium\":\"touch\",\"effects\":[{\"kind\":\"fire\",\"power\":1,\"duration\":1}]}");var p=FocusProgram.CODEC.parse(JsonOps.INSTANCE,json).getOrThrow();assertEquals("none",p.modifier());assertEquals(5,p.complexity());assertEquals(new FocusProgram("touch",List.of(new FocusProgram.Effect("fire",1,1))),p);}
    @Test void branchesHaveRealCostsAndRepeatedNodesScaleGlobally(){var root=new FocusProgram("projectile",List.of(new FocusProgram.Effect("fire",1,1)));var split=root.modifier("split_trajectory");split=split.replace(1,new FocusProgram.Branch("projectile",List.of(new FocusProgram.Effect("fire",1,1))));assertTrue(split.valid());assertEquals(23,split.complexity());assertEquals(Map.of("motus",2,"ignis",2),split.crystals());assertEquals(split,FocusProgram.CODEC.parse(JsonOps.INSTANCE,FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,split).getOrThrow()).getOrThrow());var target=root.modifier("split_target");assertEquals(16,target.complexity());assertEquals(2,target.impactEffects().size());}
    @Test void scatterSettingsAndGlobalGraphBoundsAreValidated(){var root=new FocusProgram("bolt",List.of(new FocusProgram.Effect("air",1,1)));var scatter=new FocusProgram(root.medium(),root.effects(),"scatter",10,360,1,5,false,List.of());assertTrue(scatter.valid());assertEquals(11,scatter.complexity());var invalid=new FocusProgram("touch",Collections.nCopies(8,new FocusProgram.Effect("fire",1,1))).modifier("split_target");assertFalse(invalid.valid());assertTrue(FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,invalid).error().isPresent());var malformed=FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,root).getOrThrow().getAsJsonObject();malformed.addProperty("modifier","split_target");assertTrue(FocusProgram.CODEC.parse(JsonOps.INSTANCE,malformed).error().isPresent());}
    @Test void cloudAndMineSettingsAreBudgeted(){var cloud=new FocusProgram("cloud",List.of(new FocusProgram.Effect("heal",1,1)),"none",2,10,3,30,false,List.of());assertEquals(20,cloud.complexity());assertEquals(Map.of("alkimia",1,"victus",1),cloud.crystals());assertEquals(7,new FocusProgram("mine",List.of(new FocusProgram.Effect("earth",1,1))).complexity());}
    @Test void planSettingsPersistWithoutChangingOriginalCostsAndExclusiveMediaAreRejected(){var plan=new FocusProgram("plan",List.of(new FocusProgram.Effect("break",1,1)),"none",2,10,1,5,false,List.of(),new FocusProgram.PlanSettings(2,0,1,true));assertEquals(7,plan.complexity());assertEquals(Map.of("fabrico",1,"perditio",1),plan.crystals());assertEquals("FOCUSPLAN",plan.mediumResearch());assertEquals(plan,FocusProgram.CODEC.parse(JsonOps.INSTANCE,FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,plan).getOrThrow()).getOrThrow());var invalidJson=FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,plan).getOrThrow().getAsJsonObject();invalidJson.getAsJsonObject("plan").addProperty("x",4);assertTrue(FocusProgram.CODEC.parse(JsonOps.INSTANCE,invalidJson).error().isPresent());assertEquals(plan.plan(),plan.path(0).plan());assertEquals(plan.plan(),plan.modifier("split_target").plan());assertFalse(plan.modifier("scatter").valid());assertFalse(plan.modifier("split_trajectory").valid());assertFalse(new FocusProgram("touch",plan.effects()).modifier("split_trajectory").replace(1,new FocusProgram.Branch("plan",plan.effects())).valid());}
    @Test void spellbatFriendlyBranchesKeepOriginalCostAndAspect(){var p=new FocusProgram("spellbat",List.of(new FocusProgram.Effect("heal",1,1)),"none",2,10,1,5,true,List.of());assertEquals(12,p.complexity());assertEquals(Map.of("bestia",1,"victus",1),p.crystals());assertEquals("FOCUSSPELLBAT",p.mediumResearch());assertTrue(p.modifier("split_target").path(0).friendly());assertEquals(p,FocusProgram.CODEC.parse(JsonOps.INSTANCE,FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,p).getOrThrow()).getOrThrow());}
    @Test void riftSettingsCostAndLegacyEffectsRoundTrip(){for(int depth:List.of(8,16,24,32))for(int duration=2;duration<=10;duration++){var e=new FocusProgram.Effect("rift",1,duration,depth);var p=new FocusProgram("bolt",List.of(e));assertTrue(p.valid());assertEquals(8+duration/2+depth/4,p.complexity());assertEquals(Map.of("potentia",1,"alienis",1),p.crystals());assertEquals(p,FocusProgram.CODEC.parse(JsonOps.INSTANCE,FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,p).getOrThrow()).getOrThrow());}var old=FocusProgram.Effect.CODEC.parse(JsonOps.INSTANCE,JsonParser.parseString("{\"kind\":\"fire\",\"power\":1,\"duration\":1}")).getOrThrow();assertEquals(8,old.depth());assertEquals(3,old.complexity());}
    @Test void invalidRiftAndOrdinaryDurationsAreRejectedWithoutExceptions(){for(String value:List.of("{\"kind\":\"rift\",\"power\":1,\"duration\":1}","{\"kind\":\"rift\",\"power\":1,\"duration\":11}","{\"kind\":\"rift\",\"power\":1,\"duration\":2,\"depth\":9}","{\"kind\":\"fire\",\"power\":1,\"duration\":6}"))assertTrue(FocusProgram.Effect.CODEC.parse(JsonOps.INSTANCE,JsonParser.parseString(value)).error().isPresent());assertFalse(new FocusProgram("touch",List.of(new FocusProgram.Effect("rift",1,1))).valid());}
}
